import { useState } from 'react'
import { useAuth, useMfa } from '@musikhood-dev/auth-client/react'

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@@/components/ui/dialog'
import { MfaCodeForm, type MfaCodeSubmit } from '@@/components/auth/mfa-code-form'
import { reportAuthError } from '@@/lib/auth'
import { MFA_TEXTS, mfaErrorMessage } from '@@/lib/mfa'

// Global step-up dialog: the backend answered 403 `mfa_step_up` (session without a second
// factor on a panel that requires 2FA). It cannot be dismissed without a code — the only
// alternative is logging out (auth-client resets the MFA stage on logout, so the dialog
// closes by itself). Rendered by <AuthMfaDialogs /> inside AuthProvider.
export function MfaStepUpDialog() {
  const mfa = useMfa()
  const { logout, isAuthenticated } = useAuth()
  const [error, setError] = useState<string | null>(null)

  const handleSubmit = async (data: MfaCodeSubmit) => {
    setError(null)
    try {
      await mfa.stepUp(data)
    } catch (err) {
      // Unexpected errors were already reported by the `login-error` listener (lib/auth.ts).
      setError(mfaErrorMessage(err) ?? MFA_TEXTS.verifyFailed)
    }
  }

  return (
    <Dialog open={isAuthenticated && mfa.stage === 'step-up'}>
      <DialogContent
        showCloseButton={false}
        onEscapeKeyDown={(e) => e.preventDefault()}
        onInteractOutside={(e) => e.preventDefault()}
      >
        <DialogHeader>
          <DialogTitle>Potwierdź tożsamość</DialogTitle>
          <DialogDescription>
            Ten panel wymaga weryfikacji dwuetapowej. Wpisz kod z aplikacji uwierzytelniającej, aby
            kontynuować.
          </DialogDescription>
        </DialogHeader>
        <MfaCodeForm
          isPending={mfa.stepUp.isPending}
          error={error}
          submitLabel="Potwierdź"
          onSubmit={(data) => void handleSubmit(data)}
          onCancel={() =>
            void logout().catch((err: unknown) => reportAuthError(err, MFA_TEXTS.logoutFailed))
          }
          cancelLabel="Wyloguj się"
        />
      </DialogContent>
    </Dialog>
  )
}
